<template>
	<view class="detail-page">
		<view v-if="loading" class="loading">正在加载订单详情...</view>
		<StateView v-else-if="error" title="订单详情加载失败" :description="error" action-text="重新加载" error @action="loadOrder" />
		<template v-else-if="order">
			<view class="status-panel">
				<view class="status-icon">{{ statusIcon }}</view><view><text>{{ order.statusText }}</text><text>{{ statusDescription }}</text></view>
			</view>
			<view class="progress" :class="{inactive:order.status>3}"><view v-for="(item,index) in steps" :key="item" :class="{done:index<activeStep}"><text>{{ index<activeStep?'✓':index+1 }}</text><text>{{ item }}</text></view></view>
			<view class="info-panel">
				<view class="panel-head"><text>收货信息</text></view>
				<view class="receiver"><image src="/static/icons/map-pin.png" mode="aspectFit" /><view><text>{{ order.receiverName||'--' }}　{{ maskPhone(order.receiverPhone) }}</text><text>{{ order.fullAddress||'暂无收货地址信息' }}</text></view></view>
			</view>
			<view v-if="order.logisticsCompany||order.logisticsNo" class="info-panel">
				<view class="panel-head"><text>配送信息</text><text>{{ order.status===2?'运输中':'物流信息' }}</text></view>
				<view class="info-row"><text>物流公司</text><text>{{ order.logisticsCompany||'--' }}</text></view><view class="info-row"><text>物流单号</text><text selectable>{{ order.logisticsNo||'--' }}</text></view><view v-if="order.deliveryTime" class="info-row"><text>发货时间</text><text>{{ formatDate(order.deliveryTime) }}</text></view>
			</view>
			<view class="goods-panel">
				<view class="panel-head"><text>商品清单</text><text>{{ order.items.length }} 件商品</text></view>
				<view v-for="item in order.items" :key="item.orderItemId" class="goods-item" @tap="openProduct(item)"><image :src="item.image||'/static/logo.png'" mode="aspectFill" /><view class="goods-copy"><text>{{ item.name }}</text><text v-if="item.spec">{{ item.spec }}</text><view><text>¥{{ formatPrice(item.price) }}</text><text>× {{ item.quantity }}</text></view></view><button v-if="order.status===3" @tap.stop="openReview(item)">评价</button></view>
				<view v-if="!order.items.length" class="goods-empty">暂无商品明细</view>
			</view>
			<view class="info-panel order-info">
				<view class="panel-head"><text>订单信息</text></view>
				<view class="info-row"><text>订单编号</text><text selectable>{{ order.orderNo }}</text></view><view class="info-row"><text>下单时间</text><text>{{ formatDate(order.createTime)||'--' }}</text></view><view v-if="order.payTime" class="info-row"><text>付款时间</text><text>{{ formatDate(order.payTime) }}</text></view><view v-if="order.payDeadline&&order.status===0" class="info-row"><text>支付截止</text><text>{{ formatDate(order.payDeadline) }}</text></view><view v-if="order.remark" class="info-row"><text>订单备注</text><text>{{ order.remark }}</text></view>
			</view>
			<view class="amount-panel"><view><text>商品金额</text><text>¥{{ formatPrice(order.goodsAmount) }}</text></view><view><text>运费</text><text>+¥{{ formatPrice(order.freightAmount) }}</text></view><view><text>优惠</text><text>-¥{{ formatPrice(order.discountAmount) }}</text></view><view class="payable"><text>实付款</text><text>¥{{ formatPrice(order.payAmount) }}</text></view></view>
			<view v-if="actions.length" class="action-bar"><button v-for="action in actions" :key="action.key" :class="{primary:action.primary}" :loading="operating===action.key" :disabled="Boolean(operating)" @tap="handleAction(action.key)">{{ action.label }}</button></view>
		</template>
	</view>
</template>

<script>
	import StateView from '../../components/StateView.vue'
	import { cancelOrder, deleteOrder, getOrderDetail, receiveOrder } from '../../api/index.js'
	import { formatDate, formatMoney } from '../../utils/format.js'
	import { normalizeOrderDetail } from '../../utils/normalizers.js'
	const descriptions={0:'订单已提交，请尽快完成支付',1:'付款成功，商家正在准备商品',2:'商品已发出，请注意查收',3:'订单已完成，感谢您的购买',4:'订单已取消',5:'订单款项已退回'}
	export default{
		components:{StateView},data(){return{orderNo:'',order:null,loading:true,error:'',operating:'',steps:['提交订单','付款成功','商品出库','完成']}},
		computed:{statusDescription(){return descriptions[this.order?.status]||'订单状态正在更新'},statusIcon(){return this.order?.status===3?'✓':this.order?.status>3?'!':'JD'},activeStep(){return({0:1,1:2,2:3,3:4}[this.order?.status]||0)},actions(){const status=this.order?.status;const map={0:[{key:'cancel',label:'取消订单'},{key:'pay',label:'立即付款',primary:true}],1:[{key:'cancel',label:'取消订单'}],2:[{key:'receive',label:'确认收货',primary:true}],3:[{key:'review',label:'评价订单',primary:true},{key:'delete',label:'删除订单'}],4:[{key:'delete',label:'删除订单'}],5:[{key:'delete',label:'删除订单'}]};return map[status]||[]}},
		onLoad(options){this.orderNo=String(options.orderNo||'');this.loadOrder()},onPullDownRefresh(){this.loadOrder(true)},
		methods:{formatDate,formatPrice:formatMoney,maskPhone(value){const phone=String(value||'');return /^\d{11}$/.test(phone)?`${phone.slice(0,3)}****${phone.slice(-4)}`:phone||'--'},async loadOrder(fromPullDown=false){if(!this.orderNo){this.loading=false;this.error='缺少订单编号';return}this.loading=!fromPullDown;this.error='';try{this.order=normalizeOrderDetail(await getOrderDetail(this.orderNo))}catch(error){this.order=null;this.error=error.message||'订单加载失败'}finally{this.loading=false;if(fromPullDown)uni.stopPullDownRefresh()}},openProduct(item){if(item.productId)uni.navigateTo({url:`/pages/products/detail?id=${item.productId}`})},openReview(item){uni.navigateTo({url:`/pages/orders/review?orderNo=${encodeURIComponent(this.orderNo)}&orderItemId=${item.orderItemId}`})},confirm(title,content,action){uni.showModal({title,content,confirmColor:'#e1251b',success:async(result)=>{if(!result.confirm)return;this.operating=action;try{if(action==='cancel')await cancelOrder(this.orderNo);if(action==='receive')await receiveOrder(this.orderNo);if(action==='delete'){await deleteOrder(this.orderNo);uni.showToast({title:'订单已删除',icon:'success'});setTimeout(()=>uni.navigateBack(),500);return}uni.showToast({title:'操作成功',icon:'success'});await this.loadOrder()}catch(error){uni.showToast({title:error.message||'操作失败',icon:'none'})}finally{this.operating=''}}})},handleAction(action){if(this.operating)return;if(action==='pay'){uni.navigateTo({url:`/pages/payment/index?orderNo=${encodeURIComponent(this.orderNo)}&amount=${this.order.payAmount}`});return}if(action==='review'){uni.navigateTo({url:`/pages/orders/review?orderNo=${encodeURIComponent(this.orderNo)}`});return}if(action==='cancel')this.confirm('取消订单','取消后订单将无法继续付款，确定取消吗？',action);if(action==='receive')this.confirm('确认收货','请确认已经收到商品。',action);if(action==='delete')this.confirm('删除订单','删除后无法恢复，确定删除吗？',action)}},
	}
</script>

<style scoped>
	.detail-page{min-height:100vh;padding:18rpx 20rpx 140rpx;background:#f5f6f8}.loading{display:flex;height:70vh;align-items:center;justify-content:center;color:#969da6;font-size:24rpx}.status-panel{display:flex;min-height:170rpx;padding:28rpx;align-items:center;color:#fff;border-radius:10rpx;background:#c91f17}.status-icon{display:flex;width:78rpx;height:78rpx;flex:0 0 78rpx;align-items:center;justify-content:center;border:2rpx solid rgba(255,255,255,.65);border-radius:50%;font-size:27rpx;font-weight:800}.status-panel>view:last-child{margin-left:22rpx}.status-panel text{display:block}.status-panel text:first-child{font-size:36rpx;font-weight:800}.status-panel text:last-child{margin-top:10rpx;color:rgba(255,255,255,.78);font-size:22rpx}.progress{display:grid;grid-template-columns:repeat(4,1fr);padding:25rpx 8rpx;margin-bottom:16rpx;background:#fff}.progress view{position:relative;display:flex;align-items:center;flex-direction:column;color:#a1a7af;font-size:19rpx}.progress view:not(:last-child)::after{position:absolute;top:18rpx;left:64%;width:72%;height:2rpx;background:#e0e3e7;content:''}.progress view.done:not(:last-child)::after{background:#e1251b}.progress view>text:first-child{z-index:1;display:flex;width:38rpx;height:38rpx;align-items:center;justify-content:center;border:2rpx solid #d7dbe0;border-radius:50%;background:#fff;font-size:18rpx}.progress view>text:last-child{margin-top:8rpx}.progress view.done{color:#e1251b}.progress view.done>text:first-child{color:#fff;border-color:#e1251b;background:#e1251b}.progress.inactive{opacity:.45}.info-panel,.goods-panel,.amount-panel{margin-bottom:16rpx;border:1rpx solid #eceef1;border-radius:10rpx;background:#fff}.panel-head{display:flex;height:76rpx;padding:0 22rpx;align-items:center;justify-content:space-between;border-bottom:1rpx solid #eef0f2;color:#30363e;font-size:26rpx;font-weight:700}.panel-head text:last-child{color:#e1251b;font-size:20rpx;font-weight:400}.receiver{display:flex;padding:24rpx 22rpx}.receiver image{width:40rpx;height:40rpx;flex:0 0 40rpx}.receiver>view{min-width:0;margin-left:16rpx}.receiver text{display:block;color:#3c434c;font-size:24rpx}.receiver text:last-child{margin-top:10rpx;color:#747c87;font-size:22rpx;line-height:1.5}.info-row{display:flex;padding:13rpx 22rpx;align-items:flex-start;justify-content:space-between;gap:30rpx;color:#777f89;font-size:22rpx}.info-row:first-of-type{padding-top:22rpx}.info-row:last-child{padding-bottom:22rpx}.info-row text:last-child{max-width:68%;color:#424952;text-align:right;overflow-wrap:anywhere}.goods-item{display:flex;min-height:154rpx;padding:18rpx 20rpx;align-items:center;border-bottom:1rpx solid #eef0f2}.goods-item:last-child{border-bottom:0}.goods-item>image{width:116rpx;height:116rpx;flex:0 0 116rpx;border-radius:7rpx;background:#f2f3f5}.goods-copy{min-width:0;flex:1;margin-left:16rpx}.goods-copy>text{display:block;overflow:hidden;color:#3b424b;font-size:23rpx;text-overflow:ellipsis;white-space:nowrap}.goods-copy>text:nth-child(2){margin-top:7rpx;color:#969da6;font-size:20rpx}.goods-copy>view{display:flex;margin-top:14rpx;justify-content:space-between;color:#e1251b;font-size:24rpx;font-weight:700}.goods-copy>view text:last-child{color:#7f8791;font-size:20rpx;font-weight:400}.goods-item button{width:88rpx;height:54rpx;margin:0 0 0 14rpx;padding:0;border:1rpx solid #e1251b;border-radius:6rpx;color:#e1251b;background:#fff;font-size:20rpx;line-height:54rpx}.goods-empty{padding:48rpx;color:#999fa8;text-align:center;font-size:22rpx}.amount-panel{padding:16rpx 22rpx}.amount-panel view{display:flex;padding:9rpx 0;justify-content:space-between;color:#747c87;font-size:22rpx}.amount-panel view text:last-child{color:#3d444d}.amount-panel .payable{margin-top:8rpx;padding-top:18rpx;border-top:1rpx solid #eef0f2;color:#343a42;font-weight:700}.amount-panel .payable text:last-child{color:#e1251b;font-size:30rpx}.action-bar{position:fixed;right:0;bottom:0;left:0;z-index:10;display:flex;min-height:104rpx;padding:14rpx 22rpx calc(14rpx + env(safe-area-inset-bottom));align-items:center;justify-content:flex-end;gap:12rpx;border-top:1rpx solid #e2e5e8;background:#fff}.action-bar button{height:66rpx;margin:0;padding:0 28rpx;border:1rpx solid #d7dbe0;border-radius:7rpx;color:#555d67;background:#fff;font-size:22rpx;line-height:66rpx}.action-bar button.primary{color:#fff;border-color:#e1251b;background:#e1251b}.action-bar button[disabled]{opacity:.55}
</style>
